package com.jobmatcher.security;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class TokenFilter extends OncePerRequestFilter {private final TokenService tokens;public TokenFilter(TokenService t){tokens=t;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){Long id=tokens.verify(h.substring(7));if(id!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id.toString(),null,java.util.List.of()));}chain.doFilter(req,res);}}
